root = Path(__file__).resolve().parents[1] / "docs/measurements/2026-11-14-hitscan" # TEST-SUPPORT: HITSCAN-SUMMARY-004 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix

def rows(path): # TEST-SUPPORT: HITSCAN-SUMMARY-006 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
    with path.open(encoding="utf-8") as stream: # TEST-SUPPORT: HITSCAN-SUMMARY-007 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
        return list(csv.DictReader(stream)) # TEST-SUPPORT: HITSCAN-SUMMARY-008 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix

def distribution(values): # TEST-SUPPORT: HITSCAN-SUMMARY-010 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
    values = sorted(values) # TEST-SUPPORT: HITSCAN-SUMMARY-011 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
    return {name: values[math.ceil(len(values) * q)-1] for name, q in [("p50", .5), ("p95", .95), ("p99", .99)]} if values else None # TEST-SUPPORT: HITSCAN-SUMMARY-012 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix

results = [] # TEST-SUPPORT: HITSCAN-SUMMARY-014 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
for scenario in sorted(root.iterdir()): # TEST-SUPPORT: HITSCAN-SUMMARY-015 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
    if not scenario.is_dir() or not (scenario / "runs.json").exists(): # TEST-SUPPORT: HITSCAN-SUMMARY-016 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
        continue # TEST-SUPPORT: HITSCAN-SUMMARY-017 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
    manifest = json.loads((scenario / "manifest.json").read_text()) # TEST-SUPPORT: HITSCAN-SUMMARY-018 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
    for run in json.loads((scenario / "runs.json").read_text()): # TEST-SUPPORT: HITSCAN-SUMMARY-019 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
        directory = scenario / run["run"] # TEST-SUPPORT: HITSCAN-SUMMARY-020 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
        host = directory / "host" # TEST-SUPPORT: HITSCAN-SUMMARY-021 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
        workload = json.loads((host / "workload.json").read_text()) # TEST-SUPPORT: HITSCAN-SUMMARY-022 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
        steps = [r for r in rows(host / "steps.csv") if 10 <= float(r["start_s"]) < 29] # TEST-SUPPORT: HITSCAN-SUMMARY-023 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
        publications = [r for r in rows(host / "publications.csv") if 10 <= float(r["time_s"]) < 29] # TEST-SUPPORT: HITSCAN-SUMMARY-024 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
        process = [r for r in rows(host / "process.csv") if 10 <= float(r["time_s"]) < 29] # TEST-SUPPORT: HITSCAN-SUMMARY-025 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
        wire = json.loads((directory / "impairment.json").read_text()) # TEST-SUPPORT: HITSCAN-SUMMARY-026 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
        peer_workloads = [json.loads(p.read_text()) for p in directory.glob("*/workload.json")] # TEST-SUPPORT: HITSCAN-SUMMARY-027 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
        errors = {} # TEST-SUPPORT: HITSCAN-SUMMARY-028 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
        for log in directory.glob("*/engine.log"): # TEST-SUPPORT: HITSCAN-SUMMARY-029 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
            counts = {} # TEST-SUPPORT: HITSCAN-SUMMARY-030 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
            for line in log.read_text(encoding="utf-8").splitlines(): # TEST-SUPPORT: HITSCAN-SUMMARY-031 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
                if line.startswith("ERROR:") or "Unhandled exception" in line: # TEST-SUPPORT: HITSCAN-SUMMARY-032 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
                    counts[line] = counts.get(line, 0) + 1 # TEST-SUPPORT: HITSCAN-SUMMARY-033 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
            if counts: # TEST-SUPPORT: HITSCAN-SUMMARY-034 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
                errors[log.parent.name] = counts # TEST-SUPPORT: HITSCAN-SUMMARY-035 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
        result = dict(scenario=scenario.name, run=run["run"], allPeersPassed=all(c == 0 for c in run["exitCodes"].values()), players=workload["expectedPeers"], hostConfirmedShots=workload["confirmedShots"], hostStepMs=distribution([float(r["work_ms"]) for r in steps]), hostPublicationIntervalMs=distribution([float(r["interval_ms"]) for r in publications]), hostStepAllocationBytesPerSecond=sum(int(r["allocated_bytes"]) for r in steps)/19, hostGcPauseMs=float(process[-1]["gc_pause_ms"])-float(process[0]["gc_pause_ms"]) if process else None, hostToClientsBytesPerSecond=wire["counters"]["host_to_client"]["bytes"]/run["seconds"], clientsToHostBytesPerSecond=wire["counters"]["client_to_host"]["bytes"]/run["seconds"], maxPoolHighWater=max(w["poolHighWater"] for w in peer_workloads), maxPoolDrops=max(w["poolDrops"] for w in peer_workloads), peerLocalShots=[w["localShots"] for w in peer_workloads], engineErrors=errors, arguments=manifest["arguments"], exitCodes=run["exitCodes"]) # TEST-SUPPORT: HITSCAN-SUMMARY-036 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
        results.append(result) # TEST-SUPPORT: HITSCAN-SUMMARY-037 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
