lines = ["# Hitscan combat process measurements", "", "2026-11-14. Godot 4.7.2 Mono, Release build; all peers headless on one Windows machine. Each successful run lasts about 30 seconds, with one repeat per population. These are short regression and capacity checks, not sustained performance certification.", "", "| Workload | Players | Pass | Host shots | Physics p50/p95/p99 ms | Publication p95/p99 ms | Host step allocation KiB/s | Host GC pause ms | Host outbound KiB/s | Pool high-water / drops |", "| --- | ---: | :---: | ---: | --- | --- | ---: | ---: | ---: | --- |"] # TEST-SUPPORT: HITSCAN-SUMMARY-039 | Tests: sMPGWM.Tests.PerformanceProcessTests.LocalPerformanceMatrix
